#![cfg(feature = "golden")]
//! Golden: `desk_core::day` over the demo vault gives the JSON the old app's
//! `loadDay()` gives (TEAM.md rule 4; TZ stage 2 «Проверка»).
//!
//!   cd rust && cargo test -p desk-core --features golden --test golden_day
//!
//! Fixtures: rust/fixtures/golden/{vault,expected} and rust/fixtures/edge/*,
//! regenerated by `bash rust/fixtures/tools/capture-golden.sh` (see the
//! README there). Every call into desk-core sits in `mod api` below, so a
//! name that landed differently from CONTRACTS.md is a one-line fix there.

mod common;

use common::*;
use serde_json::Value;

/// The only place that knows desk-core's names. CONTRACTS.md: «`DayInput`
/// (имя файла → байты) → `Day`. `Day` сериализуется в тот же JSON, что
/// `scripts/preview/dump.ts`».
mod api {
    use std::collections::BTreeMap;

    use chrono::NaiveDate;
    use serde_json::Value;

    pub type Files = BTreeMap<String, Vec<u8>>;

    fn date(d: &str) -> NaiveDate {
        NaiveDate::parse_from_str(d, "%Y-%m-%d").expect("golden dates are ISO")
    }

    /// Keys of `files` are vault-relative paths with `/`
    /// (`indices-kb/state/…`, `indices-kb/journal/…`, `indices-kb/config/scale.json`,
    /// `Макро-обзоры/<D> Европа.md`); the notes only need to exist.
    pub fn load_day(files: &Files, d: &str) -> Value {
        let mut input = desk_core::day::DayInput::new();
        for (k, v) in files {
            input.insert(k.clone(), v.clone());
        }
        let day: desk_core::day::Day = desk_core::day::load_day(&input, date(d));
        serde_json::to_value(&day).expect("Day serializes")
    }

    /// The dates `listDays()` gives for these file names, newest first, as ISO strings.
    pub fn list_days(files: &Files) -> Vec<String> {
        let names: Vec<&str> = files
            .keys()
            .filter_map(|k| k.strip_prefix("indices-kb/state/"))
            .collect();
        desk_core::day::list_days(names)
    }
}

#[test]
fn every_demo_day_matches_load_day() {
    let vault = read_vault(&golden().join("vault"));
    let mut r = Report::default();
    for (date, path) in expected_days(&golden().join("expected")) {
        let expected = read_json(&path);
        let actual = api::load_day(&vault, &date);
        r.json(format!("day {date}"), &expected, &actual, Cmp::default());
    }
    r.finish("golden days (rust/fixtures/golden/expected/day_*.json)");
}

#[test]
fn the_day_list_matches_list_days() {
    let vault = read_vault(&golden().join("vault"));
    let index = read_json(&golden().join("expected/index.json"));
    let expected: Vec<String> = index["days"]
        .as_array()
        .expect("days")
        .iter()
        .map(|d| str_of(d).to_owned())
        .collect();
    assert_eq!(
        api::list_days(&vault),
        expected,
        "newest first, only dates that have a scale_/macro_/review_ file"
    );
}

/// The hand-made edge vaults. `strict`: the TS JSON exactly. `no-crash`: the
/// old app threw there (recorded as `{"$error": …}`); Rust must answer a day
/// for that date instead of panicking, see the case's `decision`.
#[test]
fn edge_vaults_match_the_old_app_or_at_least_load() {
    let mut r = Report::default();
    let root = fixtures().join("edge");
    let mut cases: Vec<_> = std::fs::read_dir(&root)
        .expect("edge dir")
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.join("case.json").exists())
        .collect();
    cases.sort();
    for case in cases {
        let name = case
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();
        let meta = read_json(&case.join("case.json"));
        let vault = read_vault(&case.join("vault"));
        let index = read_json(&case.join("expected/index.json"));
        if index["ok"] == Value::Bool(true) {
            let expected: Vec<String> = index["days"]
                .as_array()
                .expect("days")
                .iter()
                .map(|d| str_of(d).to_owned())
                .collect();
            r.eq(
                format!("{name}: list_days"),
                expected,
                api::list_days(&vault),
            );
        }
        for (date, path) in expected_days(&case.join("expected")) {
            let expected = read_json(&path);
            let label = format!("{name} {date}");
            let actual = std::panic::catch_unwind(|| api::load_day(&vault, &date));
            match (str_of(&meta["compare"]), actual) {
                (_, Err(_)) => {
                    r.case();
                    r.fail(label, vec!["desk_core::day::load panicked".into()]);
                }
                ("no-crash", Ok(day)) => {
                    r.case();
                    if day["date"] != Value::String(date.clone()) {
                        r.fail(
                            label,
                            vec![format!("expected a day for {date}, got {}", day["date"])],
                        );
                    }
                }
                (_, Ok(day)) => r.json(label, &expected, &day, Cmp::default()),
            }
        }
    }
    r.finish("edge vaults (rust/fixtures/edge/*)");
}

/// TZ «Почему сейчас медленно»: the day carries shot paths; PNG bytes never
/// travel inside it (no base64, no `data:` URL), whatever desk-core grows.
#[test]
fn a_day_carries_shot_paths_never_pictures() {
    fn walk(v: &Value, at: &str, bad: &mut Vec<String>) {
        match v {
            Value::String(s) if s.starts_with("data:") || s.len() > 20_000 => {
                bad.push(at.to_owned())
            }
            Value::Array(a) => a
                .iter()
                .enumerate()
                .for_each(|(i, x)| walk(x, &format!("{at}[{i}]"), bad)),
            Value::Object(o) => o
                .iter()
                .for_each(|(k, x)| walk(x, &format!("{at}.{k}"), bad)),
            _ => {}
        }
    }
    let vault = read_vault(&golden().join("vault"));
    let day = api::load_day(&vault, "2026-09-14");
    let mut bad = Vec::new();
    walk(&day, "$", &mut bad);
    assert!(bad.is_empty(), "picture payloads inside the day: {bad:?}");
    let shots = day["eu"]["shots"]["shots"]
        .as_array()
        .expect("14.09 Europe has shots");
    for s in shots {
        let p = str_of(&s["path"]);
        assert!(
            vault.contains_key(p),
            "{p} is a vault-relative path to a file that exists"
        );
    }
}

/// A file the day does not know (another day's, a backtest, a temp file of
/// someone else's write) changes nothing in it.
#[test]
fn foreign_files_do_not_change_the_day() {
    let mut vault = read_vault(&golden().join("vault"));
    let before = api::load_day(&vault, "2026-09-15");
    for (k, v) in [
        ("indices-kb/state/scale_backtest_eu.json", b"{}".to_vec()),
        ("indices-kb/state/bias_2026-09-15.json", b"{}".to_vec()),
        (
            "indices-kb/state/regime_2026-09-15.json",
            b"{\"phase\": \"x\"}".to_vec(),
        ),
        (
            "indices-kb/state/scale_2026-09-15_eu.json.999.tmp",
            b"{\"result\": {\"needle\": 99}}".to_vec(),
        ),
        (
            "indices-kb/state/scale_2026-09-16_eu.json",
            b"{not json".to_vec(),
        ),
        ("indices-kb/state/notes.txt", b"x".to_vec()),
    ] {
        vault.insert(k.to_owned(), v);
    }
    let after = api::load_day(&vault, "2026-09-15");
    let d = json_diff(&before, &after, Cmp::default());
    assert!(d.is_empty(), "{d:#?}");
}

/// The day is a function of its bytes: the same input twice gives the same JSON.
#[test]
fn loading_is_deterministic() {
    let vault = read_vault(&golden().join("vault"));
    for d in ["2026-09-14", "2026-09-18", "2026-09-24", "2026-10-26"] {
        assert_eq!(api::load_day(&vault, d), api::load_day(&vault, d), "{d}");
    }
}
